<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Priority Queue - IDA GN Central</title>
  <style>
    :root{--navy:#16345b;--deep:#0a2039;--blue:#2367a6;--teal:#1f9a9c;--gold:#c6952d;--ink:#182231;--muted:#647286;--line:#dce5ec;--surface:#f4f8fb;--warn:#d38a1f;--risk:#c34f5b;--good:#2b8b65}
    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--surface);font-family:Inter,Aptos,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:272px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;overflow:auto;padding:22px 18px;color:#fff;background:linear-gradient(180deg,var(--navy),var(--deep))}.brand{display:flex;align-items:center;gap:12px;margin-bottom:24px}.brand img{width:48px;height:48px;padding:4px;border-radius:9px;background:#fff;object-fit:contain}.brand strong{display:block;font-size:15px}.brand span{display:block;margin-top:3px;color:#bfd0e2;font-size:11px}.nav{display:grid;gap:7px}.nav>a{display:flex;align-items:center;gap:9px;padding:10px 11px;border-radius:7px;color:#d9e5f1;text-decoration:none;font-size:14px}.nav>a::before{content:attr(data-icon);width:18px;text-align:center}.nav>a:hover,.nav>a.active{color:#fff;background:rgba(255,255,255,.14);box-shadow:inset 3px 0 0 var(--gold)}.content{padding:28px clamp(20px,4vw,54px) 48px}.eyebrow{display:block;margin-bottom:8px;color:var(--teal);font-size:12px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}h1{margin:0;color:var(--navy);font-size:clamp(28px,4vw,44px)}.intro{max-width:820px;margin:12px 0 22px;color:var(--muted);font-size:15px;line-height:1.65}.queue-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:22px}.summary-card{padding:17px;border:1px solid rgba(15,58,95,.09);border-radius:16px;background:#fff;box-shadow:0 10px 26px rgba(15,58,95,.08)}.summary-card strong{display:block;color:var(--navy);font-size:24px}.summary-card span{display:block;margin-top:4px;color:var(--muted);font-size:12px}.queue{scroll-margin-top:18px;margin-bottom:18px;padding:22px;border:1px solid rgba(15,58,95,.1);border-radius:20px;background:#fff;box-shadow:0 15px 34px rgba(15,58,95,.09)}.queue-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.queue h2{margin:0;color:var(--navy);font-size:21px}.queue-head p{margin:6px 0 0;color:var(--muted);font-size:13px}.status{flex:0 0 auto;padding:7px 10px;border-radius:999px;color:#fff;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.06em}.status.warn{background:var(--warn)}.status.good{background:var(--good)}.status.risk{background:var(--risk)}.details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.detail{padding:14px;border:1px solid var(--line);border-radius:13px;background:#f9fbfd}.detail span{display:block;margin-bottom:6px;color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.detail strong{color:#334a60;font-size:13px;line-height:1.45}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:17px}.action{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;border-radius:999px;color:#fff;background:var(--blue);font-size:12px;font-weight:900;text-decoration:none;box-shadow:0 8px 18px rgba(35,103,166,.18)}.action.secondary{color:var(--blue);background:#eef7fa;box-shadow:none}.note{margin:18px 0 0;padding:13px 15px;border-left:4px solid var(--gold);border-radius:0 10px 10px 0;color:#5c6875;background:#fff9ec;font-size:12px;line-height:1.55}@@media(max-width:850px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding:24px 18px 38px}.queue-summary,.details{grid-template-columns:1fr}.queue-head{display:block}.status{display:inline-flex;margin-top:12px}}
  </style>
  <link rel="stylesheet" href="{{ asset('assets/dashboard/gn-central/preview-assets') }}/gn-central-navigation.css">
</head>
<body>
  <div class="shell">
    <aside class="sidebar" aria-label="Primary navigation"><div class="brand"><img src="{{ asset('assets/dashboard/gn-central/preview-assets') }}/ida-global-network-logo.png" alt="IDA Global Network logo"><div><strong>Global Network Central</strong><span>Priority Queue</span></div></div><nav class="nav"><a data-icon="⌂" href="{{ route('dashboard.index') }}">Home</a><a data-icon="▤" href="{{ route('dashboard.membership-applications.index') }}">Applications</a><a data-icon="◎" href="{{ route('dashboard.members.index') }}">Global Network Members</a><a data-icon="♛" data-section="leadership" href="{{ route('dashboard.member-leadership.index') }}">Member Leadership</a>
        <a data-icon="◫" href="{{ route('dashboard.member-operations.index') }}">Member Operations</a><a data-icon="▥" href="{{ route('dashboard.membership-options.index') }}">Resources</a><a data-icon="✪" href="{{ route('dashboard.accreditation.index') }}">Institutional Accreditation</a><a class="active" data-icon="✓" href="{{ route('dashboard.priority-queue.index') }}">Priority Queue</a></nav></aside>
    <main class="content">
      <header><span class="eyebrow">Operational Worklist</span><h1>Priority Queue</h1><p class="intro">A single detailed view of items requiring review, publishing decisions or content updates. Select the relevant workspace action to continue processing.</p></header>
      <section class="queue-summary" aria-label="Queue totals"><div class="summary-card"><strong>10</strong><span>Total open items</span></div><div class="summary-card"><strong>3</strong><span>Workstreams represented</span></div><div class="summary-card"><strong>5</strong><span>Items ready for decision</span></div></section>
      <section class="queue" id="partner-applications">
        <div class="queue-head"><div><h2>Partner Applications</h2><p>Three applications are awaiting their first assigned review.</p></div><span class="status warn">Review</span></div>
        <div class="details"><div class="detail"><span>Open items</span><strong>3 partner applications</strong></div><div class="detail"><span>Required action</span><strong>Assign or begin the first application review</strong></div><div class="detail"><span>Detailed records</span><strong>Application workspace, evidence, comments and decision history</strong></div></div>
        <div class="actions"><a class="action" href="{{ route('dashboard.membership-applications.index') }}">Open Applications Workspace →</a><a class="action secondary" href="{{ route('dashboard.index') }}">Return to Home</a></div>
      </section>
      <section class="queue" id="event-submissions">
        <div class="queue-head"><div><h2>Event Submissions</h2><p>Five submitted events have completed intake and require a publishing decision.</p></div><span class="status good">Ready</span></div>
        <div class="details"><div class="detail"><span>Open items</span><strong>5 event submissions</strong></div><div class="detail"><span>Required action</span><strong>Review content, dates, permissions and visibility before publishing</strong></div><div class="detail"><span>Decision status</span><strong>Ready for an authorized publishing decision</strong></div></div>
        <p class="note">Record-level event titles and dates will appear here when the Events workspace is connected to the GN Central data layer. This queue remains the operational destination for the current five-item publishing workload.</p>
      </section>
      <section class="queue" id="resource-updates">
        <div class="queue-head"><div><h2>Resource Updates</h2><p>Two updates are pending as part of the Central toolkit refresh.</p></div><span class="status risk">Pending</span></div>
        <div class="details"><div class="detail"><span>Open items</span><strong>2 resource updates</strong></div><div class="detail"><span>Required action</span><strong>Confirm content, version status and publication readiness</strong></div><div class="detail"><span>Destination</span><strong>GN Central Resources and controlled member materials</strong></div></div>
        <div class="actions"><a class="action" href="{{ route('dashboard.membership-options.index') }}">Open Resources Workspace →</a><a class="action secondary" href="{{ route('dashboard.index') }}">Return to Home</a></div>
      </section>
    </main>
  </div>
</body>
</html>
